import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第三十一卦 鹹 澤山鹹 兌上艮下","description":"周易 - 第三十一卦 鹹 澤山鹹 兌上艮下","frontmatter":{"title":"第三十一卦 鹹 澤山鹹 兌上艮下","description":"周易 - 第三十一卦 鹹 澤山鹹 兌上艮下"},"headers":[],"relativePath":"classics/zhouyi/032.md","filePath":"classics/zhouyi/032.md"}'),l={name:"classics/zhouyi/032.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="鹹" tabindex="-1">鹹 <a class="header-anchor" href="#鹹" aria-label="Permalink to “鹹”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨，利貞，取女吉。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>鹹，感也。柔上而剛下，二氣感應以相與，止而說，男下女，是以亨利貞，取女吉也。天地感而萬物化生，聖人感人心而天下和平；觀其所感，而天地萬物之情可見矣！</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>山上有澤，鹹；君子以虛受人。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>鹹其拇。象曰：鹹其拇，志在外也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>鹹其腓，兇，居吉。象曰：雖兇，居吉，順不害也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>鹹其股，執其隨，往吝。象曰：鹹其股，亦不處也。志在隨人，所執下也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>貞吉悔亡，憧憧往來，朋從爾思。象曰：貞吉悔亡，未感害也。憧憧往來，未光大也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>鹹其脢，無悔。象曰：鹹其脢，志末也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>鹹其輔，頰，舌。象曰：鹹其輔，頰，舌，滕口說也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
